	eV, aV := reflect.ValueOf(expected), reflect.ValueOf(actual)
	if eV.Type() != aV.Type() {
		fatal(
			tb,
			msgAndArgs,
			"Not equal: %T(%#v) (expected)\n"+
				"        != %T(%#v) (actual)", expected, expected, actual, actual)
	}
	if !reflect.DeepEqual(expected, actual) {
		fatal(
			tb,
			msgAndArgs,
