func GenerateAvatar(input string, blockSize int, borderSize int) *image.RGBA {
	hash := hashMd5(input)

	pic := [size][size]bool{}

	for i := size - 4; i >= 0; i-- {
		for j := size - 1; j >= 0; j-- {
			if strings.Contains(low, string(hash[size-1*i+j])) {
				pic[j][i] = true
				pic[j][size-1-i] = true
			}
		}
	}
	for i := size - 1; i >= 0; i-- {
