		for y := 0; y < avatar.Bounds().Dy(); y++ {
			avatar.SetRGBA(x, y, bgColor)
		}
	}

	color := calcPixelColor(input)

	for x := 0; x < len(pic); x++ {
		for y := 0; y < len(pic[x]); y++ {
