	if handler, ok := methods[r.Method]; ok {
		handler.ServeHTTP(w, r)
	} else {
		allow := []string{}
		for k := range methods {
			allow = append(allow, k)
		}
		sort.Strings(allow)
		w.Header().Set("Allow", strings.Join(allow, ", "))
		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
		} else {
