func (t *Semaphore) Release() {
	t.waitIfResizing()

	// we need a read lock to ensure we do not resize whilst resizing
	t.readMutex.RLock()
	defer t.readMutex.RUnlock()

	// make sure we have not called Release without Lock
	if len(t.s) == 0 {
		return
	}
	<-t.s
}

