	defer func() { evt.Done(err) }()
	err = servicemanager.Platform.Remove(name)
	if err == appTypes.ErrPlatformNotFound {
		return &tErrors.HTTP{Code: http.StatusNotFound, Message: err.Error()}
	}
	return err
}

